pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newLimit) public {
        // Ensure the new limit is reasonable (non-zero to observe a change)
        vm.assume(newLimit > 0);

        // Record the betLimit before the call
        uint256 beforeLimit = c.currentBetLimit();

        // Owner (this contract) is the owner, so only the reference succeeds; the mutant reverts.
        // We try to call AdjustBetAmounts as owner.
        try c.AdjustBetAmounts(newLimit) {
            // If the call succeeded (reference behavior), betLimit should have changed.
            uint256 afterLimit = c.currentBetLimit();
            // In the reference, after a successful call, afterLimit equals newLimit.
            // In the mutant the call reverts, so we never reach this branch.
            assertTrue(afterLimit == newLimit && afterLimit != beforeLimit);
        } catch {
            // If the call reverted (mutant behavior), betLimit must remain unchanged.
            uint256 afterLimit = c.currentBetLimit();
            assertTrue(afterLimit == beforeLimit);
        }
    }
}

